import { Component, ChangeDetectionStrategy, Input, OnChanges, Output, EventEmitter } from '@angular/core';
import { Card, Goal, TeamType } from '@honoregaming/types';

@Component({
  selector: 'hg-event-history',
  templateUrl: './event-history.component.html',
  styleUrls: ['./event-history.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventHistoryComponent implements OnChanges {
  @Input()
  collapsable: boolean;

  @Input()
  cards: Card[];

  @Input()
  goals: Goal[];

  @Output()
  toggleEvent = new EventEmitter();

  history: (Card | Goal)[];
  displayFullHistory = false;

  TeamType = TeamType;

  ngOnChanges() {
    this.history = [...this.goals, ...this.cards];
    this.history.forEach(h => {
      if (h !== undefined && h.timeDetails?.indexOf(':') > -1) {
        h.timeDetails = h.timeDetails.slice(0, h.timeDetails.indexOf(':'));
      }
    });

    this.history.sort((o1, o2) => parseInt(o1.timeDetails, 10) - parseInt(o2.timeDetails, 10));
  }

  toggleHistory() {
    this.displayFullHistory = !this.displayFullHistory;
    this.toggleEvent.emit();
  }
}
