import { ChangeDetectionStrategy, Input, Component, HostBinding, Inject, OnChanges } from '@angular/core';
import { Match, EventStateType, EventStateDetailsType } from '@honoregaming/types';
import { DomSanitizer, SafeStyle } from '@angular/platform-browser';
import { getBackgroundForEntryPoint } from '../../sport-background.helper';
import { Scope, scopeToken } from '@honoregaming/core';

@Component({
  selector: 'hg-one-score-event-summary',
  templateUrl: './one-score-event-summary.component.html',
  styleUrls: ['./one-score-event-summary.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OneScoreEventSummaryComponent implements OnChanges {
  @Input() event: Match;
  @Input() isStickyHeader: boolean;

  EventStateDetailsType = EventStateDetailsType;
  EventStateType = EventStateType;
  score: { homeTeamScore?: number; awayTeamScore?: number } = {};
  overTimeHomeTeamScore: number;
  overTimeAwayTeamScore: number;

  @HostBinding('style.backgroundImage')
  get eventBg(): SafeStyle {
    return this.scope === Scope.Customer || this.scope === Scope.Kiosk
      ? this.sanitizer.bypassSecurityTrustStyle(getBackgroundForEntryPoint(this.event.entryPointId))
      : '';
  }

  constructor(private sanitizer: DomSanitizer, @Inject(scopeToken) private scope: Scope) {}

  ngOnChanges(): void {
    if ((!this.event.scores?.length || this.event.scores[0].type !== 'Period1') && this.event.entryPointId !== 101) {
      this.score.homeTeamScore = this.event.homeTeamScore;
      this.score.awayTeamScore = this.event.awayTeamScore;
    } else if (this.event.scores[0].type === 'Period1') {
      this.score.homeTeamScore = +this.event.scores[0].homeTeamScore;
      this.score.awayTeamScore = +this.event.scores[0].awayTeamScore;
      if (this.event.scores[1]?.type === 'Period2') {
        this.score.homeTeamScore += +this.event.scores[1].homeTeamScore;
        this.score.awayTeamScore += +this.event.scores[1].awayTeamScore;
      }
      if (this.event.scores[2]?.type === 'PeriodOvertime') {
        this.overTimeHomeTeamScore = +this.event.scores[2].homeTeamScore + this.score.homeTeamScore;
        this.overTimeAwayTeamScore = +this.event.scores[2].awayTeamScore + this.score.awayTeamScore;
      }
    }
  }
}
