export function getBackgroundForEntryPoint(entryPoint: number) {
  switch (entryPoint) {
    case 101:
      return `url('assets/sports/soccer-bg.jpg')`;
    case 102:
      return `url('assets/sports/basketball-bg.jpg')`;
    case 103:
      return `url('assets/sports/tennis-bg.jpg')`;
    case 104:
      return `url('assets/sports/rugby-bg.jpg')`;
    case 105:
      return `url('assets/sports/american-football-bg.jpg')`;
    case 106:
      return `url('assets/sports/badminton-bg.jpg')`;
    case 107:
      return `url('assets/sports/baseball-bg.jpg')`;
    case 108:
      return `url('assets/sports/darts-bg.jpg')`;
    case 109:
      return `url('assets/sports/futsal-bg.jpg')`;
    case 110:
      return `url('assets/sports/handball-bg.jpg')`;
    case 111:
      return `url('assets/sports/ice-hockey-bg.jpg')`;
    case 112:
      return `url('assets/sports/snooker-bg.jpg')`;
    case 113:
      return `url('assets/sports/table-tennis-bg.jpg')`;
    case 114:
      return `url('assets/sports/volleyball-bg.jpg')`;
    case 1000:
      return `url('assets/sports/lol-bg.png')`;
    case 1001:
      return `url('assets/sports/cs-bg.png')`;
    case 1002:
      return `url('assets/sports/dota-bg.png')`;
    case 1003:
      return `url('assets/sports/esoccer-bg.jpg')`;
    case 8019:
    case 8020:
    case 8021:
    case 8027:
    case 8028:
    case 8029:
      return `url('assets/sports/soccer-bg.jpg')`;
    default:
      return '';
  }
}
