import {
  ChangeDetectionStrategy,
  Input,
  Component,
  SimpleChanges,
  OnChanges,
  HostBinding,
  Inject
} from '@angular/core';
import { Match, EventStateType, MatchScoreType, EventStateDetailsType } from '@honoregaming/types';
import { SafeStyle, DomSanitizer } from '@angular/platform-browser';
import { getBackgroundForEntryPoint } from '../../sport-background.helper';
import { Scope, scopeToken } from '@honoregaming/core';

@Component({
  selector: 'hg-default-event-summary',
  templateUrl: './default-event-summary.component.html',
  styleUrls: ['./default-event-summary.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class DefaultEventSummaryComponent implements OnChanges {
  @Input()
  event: Match;
  @Input() isStickyHeader: boolean;

  EventStateDetailsType = EventStateDetailsType;

  @HostBinding('style.backgroundImage')
  get eventBg(): SafeStyle {
    return this.scope == Scope.Customer || this.scope === Scope.Kiosk
      ? this.sanitizer.bypassSecurityTrustStyle(getBackgroundForEntryPoint(this.event.entryPointId))
      : '';
  }

  EventStateType = EventStateType;

  currentScoreType: MatchScoreType;

  constructor(private sanitizer: DomSanitizer, @Inject(scopeToken) private scope: Scope) {}

  ngOnChanges(_changes: SimpleChanges) {
    if (this.event.scores?.length) {
      this.currentScoreType = this.event.scores[this.event.scores.length - 1].type;
    }
  }
}
