import {
  ChangeDetectionStrategy,
  Input,
  Component,
  ViewChild,
  ElementRef,
  HostListener,
  ChangeDetectorRef,
  Output,
  EventEmitter
} from '@angular/core';
import { Match, EventStateType } from '@honoregaming/types';

@Component({
  selector: 'hg-event-summary',
  templateUrl: './event-summary.component.html',
  styleUrls: ['./event-summary.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EventSummaryComponent {
  @Input()
  event: Match;
  @Input() isStickyHeader: boolean;

  @Output()
  blockHeaderHeight = new EventEmitter<number>();

  @Output()
  toggleEventHistory = new EventEmitter();

  EventStateType = EventStateType;

  blockEventElement: ElementRef;
  blockEventHeight = 0;

  @ViewChild('blockEventHeight', { read: ElementRef }) set content(content: ElementRef) {
    if (content) {
      this.updateHeaderHeight(content);
    }
  }

  @HostListener('window:resize', ['$event'])
  @HostListener('window:scroll', ['$event'])
  onWindowEvent(event: Event) {
    if (event) {
      this.updateHeaderHeight();
    }
  }

  constructor(public cdRef: ChangeDetectorRef) {}

  updateHeaderHeight(content?: ElementRef) {
    if (content) {
      this.blockEventElement = content;
    }

    if (this.blockEventElement) {
      this.blockEventHeight = this.blockEventElement.nativeElement?.childNodes[0].clientHeight;
      this.blockHeaderHeight.emit(this.blockEventHeight);
      this.cdRef.detectChanges();
    }
  }
}
